import { Link, useNavigate, useRouterState } from "@tanstack/react-router";
import {
  Activity, AlertTriangle, Ambulance, ArrowRight, Bluetooth, Bot, CalendarDays, Check, ChevronRight, ClipboardList,
  CloudUpload, Droplets, FileHeart, HeartPulse, Home, Languages, Lightbulb, Menu, MessageCircle,
  Mic, Moon, Sun, Pencil, PersonStanding, Pill, Plus, Settings, ShieldCheck, Smartphone, Stethoscope, UserRound, Watch, Wind, X,
} from "lucide-react";
import { useContext, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import type { UIMessage } from "ai";

import { Conversation, ConversationContent, ConversationEmptyState, ConversationScrollButton } from "@/components/ai-elements/conversation";
import { Message, MessageContent, MessageResponse } from "@/components/ai-elements/message";
import { PromptInput, PromptInputFooter, PromptInputSubmit, PromptInputTextarea } from "@/components/ai-elements/prompt-input";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { answerHealthQuestion, compareRows, journeyEvents, records, translations, type ChatThread, type JourneyEvent, type Language } from "@/lib/health-data";
import { defaultHealthState, loadHealthState, saveHealthState, type HealthState } from "@/lib/health-store";
import { HealthLanguageContext, Translated, translateHealthText } from "@/lib/health-localization";
import { cn } from "@/lib/utils";

type Section = "dashboard" | "journey" | "records" | "copilot" | "medications" | "appointments" | "insights" | "exercises" | "emergency" | "profile" | "settings";

const sectionPath: Record<Section, string> = {
  dashboard: "/", journey: "/journey", records: "/records", copilot: "/copilot", medications: "/medications",
  appointments: "/appointments", insights: "/insights", exercises: "/exercises", emergency: "/emergency", profile: "/profile", settings: "/settings",
};

const icons: Record<Section, typeof Home> = {
  dashboard: Home, journey: Activity, records: FileHeart, copilot: Bot, medications: Pill,
  appointments: CalendarDays, insights: Lightbulb, exercises: PersonStanding, emergency: Ambulance, profile: UserRound, settings: Settings,
};

const sectionLabel: Record<Section, string> = { dashboard: "Dashboard", journey: "Health Journey", records: "Medical Records", copilot: "AI Copilot", medications: "Medications", appointments: "Appointments", insights: "Insights", exercises: "Healthy Exercises", emergency: "Emergency Services", profile: "Profile", settings: "Settings" };

const eventIcon = { visit: Stethoscope, test: Activity, result: FileHeart, prescription: Pill, followup: HeartPulse };

function BrandMark() {
  return <div className="relative grid size-10 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground shadow-soft"><HeartPulse className="size-5" /><span className="absolute -right-1 -top-1 size-2.5 rounded-full border-2 border-sidebar bg-health-green" /></div>;
}

export function HealthPilotApp({ section, threadId }: { section: Section; threadId?: string }) { 
  const navigate = useNavigate();
  const pathname = useRouterState({ select: (state) => state.location.pathname });
  const [hydrated, setHydrated] = useState(false);
  const [state, setState] = useState<HealthState>(defaultHealthState);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [uploadOpen, setUploadOpen] = useState(false);
  const [deviceOpen, setDeviceOpen] = useState(false);
  const [alertOpen, setAlertOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<JourneyEvent | null>(null);
  const [toast, setToast] = useState("");
  const language = state.language;
  const languageForAttributes = language;
  const t = translations[language];

  useEffect(() => {
    setState(loadHealthState());
    setHydrated(true);
  }, []);
  useEffect(() => {
    if (hydrated) saveHealthState(state);
  }, [hydrated, state]);
  useEffect(() => {
    setMobileOpen(false);
  }, [pathname]);
  useEffect(() => {
    if (!toast) return;
    const timer = window.setTimeout(() => setToast(""), 2800);
    return () => window.clearTimeout(timer);
  }, [toast]);

  const createThread = (seed?: string) => {
    const id = crypto.randomUUID();
    const thread: ChatThread = { id, title: seed?.slice(0, 34) || "New health question", updatedAt: Date.now(), messages: [] };
    setState((current) => ({ ...current, threads: [thread, ...current.threads] }));
    void navigate({ to: "/chat/$threadId", params: { threadId: id } });
  };

  const setLanguage = (next: Language) => setState((current) => ({ ...current, language: next }));

  useEffect(() => {
    if (!hydrated) return;
    document.documentElement.classList.toggle("dark", state.theme === "dark");
    document.documentElement.lang = state.language === "te" ? "te" : "en";
  }, [hydrated, state.theme, state.language]);

  if (!hydrated) return <div className="min-h-screen bg-background" />;

  return (
    <HealthLanguageContext.Provider value={language}><div className="flex min-h-svh bg-background text-foreground">
      <Translated>{mobileOpen && <button aria-label={translateHealthText("Close navigation", languageForAttributes)} className="fixed inset-0 z-40 bg-overlay md:hidden" onClick={() => setMobileOpen(false)} />}</Translated>
      <aside className={cn("fixed inset-y-0 left-0 z-50 flex w-64 flex-col border-r border-sidebar-border bg-sidebar transition-transform md:sticky md:top-0 md:h-svh md:translate-x-0", mobileOpen ? "translate-x-0" : "-translate-x-full")}>
        <div className="flex items-center gap-3 px-5 py-6">
          <BrandMark /><div className="min-w-0"><p className="font-display text-lg font-bold leading-none"><Translated>{"HealthPilot"}</Translated></p><p className="mt-1 text-[10px] font-bold uppercase text-primary"><Translated>{"AI Copilot"}</Translated></p></div>
          <Button className="ml-auto md:hidden" size="icon" variant="ghost" onClick={() => setMobileOpen(false)} aria-label={translateHealthText("Close menu", languageForAttributes)}><X /></Button>
        </div>
        <nav className="flex-1 space-y-1 px-3">
          <Translated>{(Object.keys(sectionPath) as Section[]).map((item) => {
            const Icon = icons[item];
            const active = item === section || (item === "copilot" && section === "copilot");
            return <Link key={item} to={sectionPath[item]} className={cn("flex h-11 items-center gap-3 rounded-lg px-3 text-sm font-medium text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent hover:text-sidebar-accent-foreground", active && "bg-sidebar-accent text-sidebar-primary shadow-inset")}><Icon className="size-4 shrink-0" /><span><Translated>{item in t ? t[item as keyof typeof t] : sectionLabel[item]}</Translated></span></Link>;
          })}</Translated>
        </nav>
        <div className="m-4 border-t border-sidebar-border pt-4">
          <div className="flex gap-2 text-xs text-muted-foreground"><ShieldCheck className="mt-0.5 size-4 shrink-0 text-primary" /><p><Translated>{"HealthPilot AI organizes health information. It does not diagnose or replace healthcare professionals."}</Translated></p></div>
        </div>
      </aside>

      <div className="min-w-0 flex-1">
        <header className="sticky top-0 z-30 grid min-h-16 grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3 border-b border-border/70 bg-background/90 px-4 backdrop-blur-xl lg:px-8">
          <Button className="md:hidden" size="icon" variant="ghost" onClick={() => setMobileOpen(true)} aria-label={translateHealthText("Open navigation", languageForAttributes)}><Menu /></Button>
          <div className="min-w-0"><p className="truncate text-sm font-semibold"><Translated>{section in t ? t[section as keyof typeof t] : sectionLabel[section]}</Translated></p><p className="truncate text-xs text-muted-foreground"><Translated>{state.patientName}</Translated></p></div>
          <div className="flex shrink-0 flex-wrap items-center justify-end gap-2">
            <div className="flex items-center gap-0.5 rounded-md border border-border bg-muted p-0.5" role="group" aria-label={translateHealthText("Appearance", languageForAttributes)}>
              <Button size="icon" variant={state.theme === "light" ? "secondary" : "ghost"} aria-label={translateHealthText("Light mode", languageForAttributes)} title={translateHealthText("Light mode", languageForAttributes)} aria-pressed={state.theme === "light"} onClick={() => setState(s => ({ ...s, theme: "light" }))}><Sun /></Button>
              <Button size="icon" variant={state.theme === "dark" ? "secondary" : "ghost"} aria-label={translateHealthText("Dark mode", languageForAttributes)} title={translateHealthText("Dark mode", languageForAttributes)} aria-pressed={state.theme === "dark"} onClick={() => setState(s => ({ ...s, theme: "dark" }))}><Moon /></Button>
            </div>
            <div className="hidden items-center rounded-md border border-border bg-muted p-1 sm:flex">
              <Button variant="ghost" size="sm" className={cn("rounded px-2 py-1 text-xs font-semibold", language === "en" && "bg-background text-primary shadow-sm")} onClick={() => setLanguage("en")}><Translated>{"English"}</Translated></Button>
              <Button variant="ghost" size="sm" className={cn("rounded px-2 py-1 text-xs font-semibold", language === "te" && "bg-background text-primary shadow-sm")} onClick={() => setLanguage("te")}><Translated>{"తెలుగు"}</Translated></Button>
            </div>
            <Button size="icon" variant="outline" onClick={() => setLanguage(language === "en" ? "te" : "en")} aria-label={translateHealthText("Switch language", languageForAttributes)} className="sm:hidden"><Languages /></Button>
            <Button variant="outline" className="hidden sm:inline-flex" onClick={() => setDeviceOpen(true)}><Watch /><Translated>{state.deviceConnected ? "Synced" : t.connect}</Translated></Button>
            <Button size="icon" variant="ghost" onClick={() => setProfileOpen(true)} aria-label={translateHealthText("Edit names", languageForAttributes)}><Pencil /></Button>
            <button onClick={() => setProfileOpen(true)} aria-label={translateHealthText("Edit profile names", languageForAttributes)} className="grid size-9 place-items-center rounded-full bg-secondary font-bold text-secondary-foreground"><Translated>{getInitials(state.patientName)}</Translated></button>
          </div>
        </header>

        <main className="mx-auto w-full max-w-[1500px] px-4 py-6 lg:px-8 lg:py-8">
          <Translated>{section === "dashboard" && <Dashboard language={language} state={state} onUpload={() => setUploadOpen(true)} onAsk={() => createThread()} onDevice={() => setDeviceOpen(true)} onEvent={setSelectedEvent} onAlert={() => setAlertOpen(true)} />}</Translated>
          <Translated>{section === "journey" && <JourneyPage onEvent={setSelectedEvent} />}</Translated>
          <Translated>{section === "records" && <RecordsPage onUpload={() => setUploadOpen(true)} onAlert={() => setAlertOpen(true)} onAsk={(q) => createThread(q)} />}</Translated>
          <Translated>{section === "copilot" && <CopilotPage state={state} setState={setState} threadId={threadId} onNew={() => createThread()} />}</Translated>
          <Translated>{section === "medications" && <MedicationsPage state={state} setState={setState} notify={setToast} />}</Translated>
          <Translated>{section === "appointments" && <AppointmentsPage doctorName={state.doctorName} onAsk={(q) => createThread(q)} />}</Translated>
          <Translated>{section === "insights" && <InsightsPage onAsk={(q) => createThread(q)} />}</Translated>
          <Translated>{section === "exercises" && <ExercisesPage />}</Translated>
          <Translated>{section === "emergency" && <EmergencyPage />}</Translated>
          <Translated>{section === "profile" && <ProfilePage state={state} onEdit={() => setProfileOpen(true)} />}</Translated>
          <Translated>{section === "settings" && <SettingsPage state={state} setState={setState} />}</Translated>
        </main>
      </div>

      <UploadDialog open={uploadOpen} onOpenChange={setUploadOpen} onSaved={() => { setUploadOpen(false); setToast("Record saved and connected to your journey"); }} onCritical={() => { setUploadOpen(false); setAlertOpen(true); }} />
      <DeviceDialog open={deviceOpen} onOpenChange={setDeviceOpen} onConnect={() => { setState((current) => ({ ...current, deviceConnected: true, metrics: { steps: 8472, heartRate: 74, sleep: 7.6, water: 7 } })); setDeviceOpen(false); setToast("Wearable data synchronized"); }} />
      <AlertDialog open={alertOpen} onOpenChange={setAlertOpen} />
      <ProfileDialog open={profileOpen} onOpenChange={setProfileOpen} state={state} setState={setState} />
      <EventDialog event={selectedEvent} onOpenChange={(open) => !open && setSelectedEvent(null)} onAsk={(q) => { setSelectedEvent(null); createThread(q); }} />
      <Translated>{toast && <div className="fixed bottom-5 left-1/2 z-[80] flex -translate-x-1/2 items-center gap-2 rounded-lg bg-foreground px-4 py-3 text-sm font-semibold text-background shadow-xl"><Check className="size-4 text-health-green" /><Translated>{toast}</Translated></div>}</Translated>
    </div></HealthLanguageContext.Provider>
  );
}

function getInitials(name: string) { return name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase() ?? "").join("") || "HP"; }

function Dashboard({ language, state, onUpload, onAsk, onDevice, onEvent, onAlert }: { language: Language; state: HealthState; onUpload: () => void; onAsk: () => void; onDevice: () => void; onEvent: (e: JourneyEvent) => void; onAlert: () => void }) { const languageForAttributes = useContext(HealthLanguageContext); 
  const t = translations[language];
  return <div className="space-y-8">
    <section className="relative overflow-hidden rounded-xl border border-border bg-hero p-6 shadow-soft sm:p-8 lg:p-10">
      <div className="relative z-10 max-w-3xl"><p className="mb-3 text-xs font-bold uppercase text-primary"><Translated>{t.greeting}</Translated><Translated>{", "}</Translated><Translated>{state.patientName}</Translated></p><h1 className="font-display text-4xl font-semibold leading-tight sm:text-5xl lg:text-6xl"><Translated>{t.hero}</Translated></h1><p className="mt-5 max-w-2xl text-base leading-7 text-muted-foreground sm:text-lg"><Translated>{t.subtitle}</Translated></p><div className="mt-7 flex flex-wrap gap-3"><Button size="lg" onClick={onUpload}><CloudUpload /><Translated>{t.upload}</Translated></Button><Button size="lg" variant="outline" onClick={onAsk}><Bot /><Translated>{t.ask}</Translated></Button><Button size="lg" variant="ghost" onClick={onDevice}><Watch /><Translated>{state.deviceConnected ? "Device synced" : t.connect}</Translated></Button></div></div>
      <div className="mt-10 grid grid-cols-2 gap-y-6 border-t border-border/70 pt-7 sm:grid-cols-4">
        <Translated>{[[FileHeart,"Medical Records"],[Bot,"AI Understanding"],[Activity,"Connected Journey"],[MessageCircle,"Doctor Conversation"]].map(([I,label],index) => { const Icon = I as typeof FileHeart; return <div key={label as string} className="relative flex items-center gap-3 text-xs font-semibold sm:flex-col sm:text-center"><div className="grid size-10 place-items-center rounded-lg bg-background text-primary shadow-sm"><Icon /></div><span><Translated>{label as string}</Translated></span><Translated>{index < 3 && <div className="absolute left-[70%] top-5 hidden h-px w-[60%] border-t border-dashed border-primary/40 sm:block" />}</Translated></div>; })}</Translated>
      </div>
    </section>
    <section><SectionHeading eyebrow="The story of your health" title={translateHealthText("Your Health Journey", languageForAttributes)} action={<Link to="/journey" className="text-sm font-semibold text-primary"><Translated>{"Open journey "}</Translated><ArrowRight className="inline size-4" /></Link>} /><JourneyStrip onEvent={onEvent} /></section>
    <section className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]">
      <div className="space-y-5"><div className="rounded-lg border border-border bg-card p-6 shadow-soft"><p className="text-xs font-bold uppercase text-muted-foreground"><Translated>{"Simple health summary"}</Translated></p><p className="mt-3 font-display text-2xl leading-snug"><Translated>{"Over the last two months you had 2 blood tests, 1 doctor visit and 2 new medicines. Your next review is on 14 October."}</Translated></p></div><div><SectionHeading eyebrow="What needs your attention?" title={translateHealthText("A clear next step", languageForAttributes)} /><div className="grid gap-4 sm:grid-cols-2"><ActionCard icon={Activity} title={translateHealthText("4 values changed in your latest report", languageForAttributes)} action="See what changed" to="/records" /><button onClick={onAlert} className="text-left"><ActionCard icon={AlertTriangle} title={translateHealthText("Know what a critical record alert looks like", languageForAttributes)} action="View safety alert" /></button></div></div></div>
      <div className="space-y-4"><UpcomingCard doctorName={state.doctorName} /><MetricGrid state={state} /></div>
    </section>
    <section><SectionHeading eyebrow="Recent AI insights" title={translateHealthText("Understand the change, not just the number", languageForAttributes)} /><div className="grid gap-4 md:grid-cols-3"><InsightCard title={translateHealthText("Haemoglobin moved upward", languageForAttributes)} body="The latest report is 0.8 g/dL higher than August." source="2 blood reports" /><InsightCard title={translateHealthText("Vitamin D improved", languageForAttributes)} body="The measured value increased from 16 to 24 ng/mL." source="2 blood reports" /><InsightCard title={translateHealthText("A review is approaching", languageForAttributes)} body="Bring your latest report and current medication list." source="Appointment · 14 Oct" /></div></section>
    <ExercisePreview />
  </div>;
}

function SectionHeading({ eyebrow, title, action }: { eyebrow: string; title: string; action?: ReactNode }) { return <div className="mb-4 grid grid-cols-[minmax(0,1fr)_auto] items-end gap-4"><div className="min-w-0"><p className="text-xs font-bold uppercase text-primary"><Translated>{eyebrow}</Translated></p><h2 className="mt-1 break-words font-display text-2xl font-semibold sm:text-3xl"><Translated>{title}</Translated></h2></div><Translated>{action}</Translated></div>; }

function JourneyStrip({ onEvent }: { onEvent: (e: JourneyEvent) => void }) { return <div className="overflow-x-auto rounded-lg border border-border bg-card p-6 shadow-soft"><div className="relative grid min-w-[760px] grid-cols-5 gap-4 before:absolute before:left-[9%] before:right-[9%] before:top-7 before:border-t before:border-dashed before:border-primary/50"><Translated>{journeyEvents.map((event) => { const Icon = eventIcon[event.type]; return <button key={event.id} onClick={() => onEvent(event)} className="group relative z-10 flex flex-col items-center text-center"><div className="grid size-14 place-items-center rounded-full border border-primary/30 bg-background text-primary transition-transform group-hover:-translate-y-1 group-hover:shadow-soft"><Icon className="size-5" /></div><span className="mt-3 text-[10px] font-bold text-muted-foreground"><Translated>{event.shortDate}</Translated></span><span className="mt-1 text-sm font-semibold"><Translated>{event.title}</Translated></span></button>; })}</Translated></div></div>; }

function ActionCard({ icon: Icon, title, action, to }: { icon: typeof Activity; title: string; action: string; to?: string }) { const body = <div className="rounded-lg border border-border bg-card p-5 shadow-soft transition-transform hover:-translate-y-0.5"><Icon className="size-5 text-primary" /><p className="mt-5 font-semibold"><Translated>{title}</Translated></p><p className="mt-2 text-sm font-semibold text-primary"><Translated>{action}</Translated> <ArrowRight className="inline size-4" /></p></div>; return to ? <Link to={to}><Translated>{body}</Translated></Link> : body; }
function UpcomingCard({ doctorName }: { doctorName: string }) { return <div className="rounded-lg border border-border bg-card p-5 shadow-soft"><p className="text-xs font-bold uppercase text-muted-foreground"><CalendarDays className="mr-2 inline size-4" /><Translated>{"Upcoming appointment"}</Translated></p><p className="mt-4 text-lg font-bold"><Translated>{doctorName}</Translated></p><p className="text-sm text-muted-foreground"><Translated>{"Wed, 14 Oct · 10:30 AM"}</Translated></p><Button asChild className="mt-4" size="sm"><Link to="/appointments"><Translated>{"Prepare for my visit "}</Translated><ArrowRight /></Link></Button></div>; }
function MetricGrid({ state }: { state: HealthState }) { const m = state.metrics; return <div className="grid grid-cols-2 gap-3"><Translated>{[[Activity,m.steps.toLocaleString(),"Steps"],[HeartPulse,`${m.heartRate} bpm`,"Heart rate"],[Moon,`${m.sleep} hrs`,"Sleep"],[Droplets,`${m.water}/8`,"Water"]].map(([I,value,label]) => { const Icon=I as typeof Activity; return <div key={label as string} className="rounded-lg border border-border bg-card p-4"><Icon className="size-4 text-primary" /><p className="mt-3 text-lg font-bold"><Translated>{value as string}</Translated></p><p className="text-xs text-muted-foreground"><Translated>{label as string}</Translated></p></div>; })}</Translated></div>; }
function InsightCard({ title, body, source }: { title: string; body: string; source: string }) { return <div className="rounded-lg border border-border bg-card p-5 shadow-soft"><Lightbulb className="size-5 text-warning" /><h3 className="mt-4 font-semibold"><Translated>{title}</Translated></h3><p className="mt-2 text-sm leading-6 text-muted-foreground"><Translated>{body}</Translated></p><p className="mt-4 text-xs font-semibold text-primary"><Translated>{"Why am I seeing this? · "}</Translated><Translated>{source}</Translated></p></div>; }

function JourneyPage({ onEvent }: { onEvent: (e: JourneyEvent) => void }) { const languageForAttributes = useContext(HealthLanguageContext);  return <div><SectionHeading eyebrow="Connected medical history" title={translateHealthText("Your Health Journey", languageForAttributes)} /><p className="mb-8 max-w-2xl text-muted-foreground"><Translated>{"Follow the thread from first test to next conversation. Every connection is grounded in your saved records."}</Translated></p><div className="relative mx-auto max-w-4xl space-y-0 before:absolute before:bottom-8 before:left-7 before:top-8 before:w-px before:bg-border sm:before:left-1/2"><Translated>{journeyEvents.map((event,index) => { const Icon=eventIcon[event.type]; return <button key={event.id} onClick={() => onEvent(event)} className={cn("relative grid w-full grid-cols-[56px_minmax(0,1fr)] gap-4 pb-8 text-left sm:grid-cols-[1fr_72px_1fr]", index%2 ? "" : "")}><div className={cn("hidden rounded-lg border border-border bg-card p-5 shadow-soft sm:block", index%2 ? "invisible" : "")}><p className="text-xs font-bold text-primary"><Translated>{event.shortDate}</Translated></p><h3 className="mt-2 font-semibold"><Translated>{event.title}</Translated></h3><p className="mt-2 text-sm text-muted-foreground"><Translated>{event.detail}</Translated></p></div><div className="z-10 grid size-14 place-items-center rounded-full border border-primary/30 bg-background text-primary shadow-sm"><Icon /></div><div className={cn("rounded-lg border border-border bg-card p-5 shadow-soft", index%2 ? "" : "sm:invisible")}><p className="text-xs font-bold text-primary"><Translated>{event.shortDate}</Translated></p><h3 className="mt-2 font-semibold"><Translated>{event.title}</Translated></h3><p className="mt-2 text-sm text-muted-foreground"><Translated>{event.detail}</Translated></p></div></button>; })}</Translated></div></div>; }

function RecordsPage({ onUpload, onAlert, onAsk }: { onUpload: () => void; onAlert: () => void; onAsk: (q: string) => void }) { const languageForAttributes = useContext(HealthLanguageContext);  const [record, setRecord] = useState(records[0] ?? { id: "latest", name: "Latest report", date: "15 Sep 2026", type: "Lab report", summary: "No report details available.", critical: false }); return <div className="space-y-8"><div className="grid grid-cols-[minmax(0,1fr)_auto] items-end gap-4"><SectionHeading eyebrow="Medical record intelligence" title={translateHealthText("Records that explain themselves", languageForAttributes)} /><Button onClick={onUpload}><CloudUpload /><Translated>{"Upload record"}</Translated></Button></div><div className="grid gap-5 lg:grid-cols-[340px_minmax(0,1fr)]"><div className="space-y-2"><Translated>{records.map((item) => <button key={item.id} onClick={() => setRecord(item)} className={cn("w-full rounded-lg border p-4 text-left transition-colors", record.id===item.id ? "border-primary bg-accent" : "border-border bg-card hover:bg-muted")}><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-lg bg-background text-primary"><FileHeart /></div><div className="min-w-0"><p className="truncate font-semibold"><Translated>{item.name}</Translated></p><p className="text-xs text-muted-foreground"><Translated>{item.type}</Translated> <Translated>{"· "}</Translated><Translated>{item.date}</Translated></p></div></div></button>)}</Translated></div><div className="rounded-lg border border-border bg-card p-6 shadow-soft"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase text-primary"><Translated>{record.type}</Translated></p><h2 className="mt-1 font-display text-3xl font-semibold"><Translated>{record.name}</Translated></h2><p className="mt-1 text-sm text-muted-foreground"><Translated>{record.date}</Translated></p></div><Button variant="outline" onClick={() => onAsk(`Explain ${record.name}`)}><Bot /><Translated>{"Ask Copilot"}</Translated></Button></div><Tabs defaultValue="simple" className="mt-6"><TabsList><TabsTrigger value="medical"><Translated>{"Medical"}</Translated></TabsTrigger><TabsTrigger value="simple"><Translated>{"Simple"}</Translated></TabsTrigger><TabsTrigger value="questions"><Translated>{"Questions"}</Translated></TabsTrigger></TabsList><TabsContent value="medical" className="mt-5 rounded-lg bg-muted p-5 text-sm leading-7"><Translated>{"Hb 11.6 g/dL · 25-OH Vitamin D 24 ng/mL · FBS 94 mg/dL. Compare with prior specimen dated 12 Aug 2026."}</Translated></TabsContent><TabsContent value="simple" className="mt-5 rounded-lg bg-muted p-5"><p className="text-sm leading-7"><Translated>{record.summary}</Translated> <Translated>{"This is a plain-language description of the recorded values, not a diagnosis."}</Translated></p></TabsContent><TabsContent value="questions" className="mt-5 rounded-lg bg-muted p-5"><ul className="space-y-3 text-sm"><li><Translated>{"• Are these changes progressing as expected?"}</Translated></li><li><Translated>{"• Should I continue both medicines at the same dose?"}</Translated></li><li><Translated>{"• When should this test be repeated?"}</Translated></li></ul></TabsContent></Tabs></div></div><ComparisonTool onAsk={onAsk} /><button onClick={onAlert} className="text-sm font-semibold text-destructive underline-offset-4 hover:underline"><Translated>{"Preview a critical record safety alert"}</Translated></button></div>; }

function ComparisonTool({ onAsk }: { onAsk: (q: string) => void }) { const languageForAttributes = useContext(HealthLanguageContext);  return <section><SectionHeading eyebrow="What changed?" title={translateHealthText("Previous vs latest blood report", languageForAttributes)} action={<Button variant="outline" onClick={() => onAsk("Explain what changed between my blood reports")}><Translated>{"Explain the changes"}</Translated></Button>} /><div className="overflow-hidden rounded-lg border border-border bg-card shadow-soft"><div className="grid grid-cols-[minmax(110px,1fr)_1fr_auto_1fr] gap-3 border-b border-border bg-muted px-4 py-3 text-xs font-bold uppercase text-muted-foreground"><span><Translated>{"Marker"}</Translated></span><span><Translated>{"12 Aug"}</Translated></span><span /><span><Translated>{"15 Sep"}</Translated></span></div><Translated>{compareRows.map((row) => <div key={row.label} className="grid grid-cols-[minmax(110px,1fr)_1fr_auto_1fr] items-center gap-3 border-b border-border px-4 py-4 last:border-0"><div><p className="font-semibold"><Translated>{row.label}</Translated></p><p className="mt-1 hidden text-xs text-muted-foreground sm:block"><Translated>{row.note}</Translated></p></div><span className="text-sm text-muted-foreground"><Translated>{row.before}</Translated></span><ArrowRight className="size-4 text-primary" /><span className="text-sm font-bold text-primary"><Translated>{row.after}</Translated></span></div>)}</Translated></div></section>; }

function CopilotPage({ state, setState, threadId, onNew }: { state: HealthState; setState: (updater: (s: HealthState) => HealthState) => void; threadId: string | undefined; onNew: () => void }) { const languageForAttributes = useContext(HealthLanguageContext); 
  const navigate = useNavigate();
  const [input, setInput] = useState("");
  const [status, setStatus] = useState<"ready"|"submitted">("ready");
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const active = state.threads.find((thread) => thread.id === threadId);
  const thread = active ?? state.threads[0];
  useEffect(() => {
    if (thread) return;
    const id = crypto.randomUUID();
    const initialThread: ChatThread = { id, title: "New health question", updatedAt: Date.now(), messages: [] };
    setState((current) => ({ ...current, threads: [initialThread, ...current.threads] }));
    void navigate({ to: "/chat/$threadId", params: { threadId: id } });
  }, [navigate, setState, thread]);
  useEffect(() => { if (!threadId && thread) void navigate({ to: "/chat/$threadId", params: { threadId: thread.id } }); }, [navigate, thread, threadId]);
  useEffect(() => { textareaRef.current?.focus(); }, [threadId, status]);
  const uiMessages = useMemo<UIMessage[]>(() => (thread?.messages ?? []).map((m) => ({ id: m.id, role: m.role, parts: [{ type: "text", text: m.text }] })), [thread]);

  const submit = (text: string) => {
    const clean = text.trim(); if (!clean) return;
    let target = thread;
    if (!target) {
      const id = crypto.randomUUID();
      target = { id, title: clean.slice(0,34), updatedAt: Date.now(), messages: [] };
      setState((current) => ({ ...current, threads: [target as ChatThread, ...current.threads] }));
      void navigate({ to: "/chat/$threadId", params: { threadId: id } });
    }
    const targetId = target.id;
    const userMessage = { id: crypto.randomUUID(), role: "user" as const, text: clean };
    setState((current) => ({ ...current, threads: current.threads.map((item) => item.id===targetId ? { ...item, title: item.messages.length ? item.title : clean.slice(0,34), updatedAt: Date.now(), messages: [...item.messages,userMessage] } : item) }));
    setInput(""); setStatus("submitted");
    window.setTimeout(() => {
      const answer = answerHealthQuestion(clean, state.language, state.patientName, state.doctorName);
      setState((current) => ({ ...current, threads: current.threads.map((item) => item.id===targetId ? { ...item, updatedAt: Date.now(), messages: [...item.messages,{ id: crypto.randomUUID(), role: "assistant" as const, text: answer.text, sources: answer.sources, localizedText: { en: answerHealthQuestion(clean, "en", state.patientName, state.doctorName).text, te: answerHealthQuestion(clean, "te", state.patientName, state.doctorName).text } }] } : item) }));
      setStatus("ready");
      if ("speechSynthesis" in window) { const utterance = new SpeechSynthesisUtterance(answer.text.replaceAll("**","")); utterance.lang = state.language === "te" ? "te-IN" : "en-IN"; window.speechSynthesis.speak(utterance); }
    }, 700);
  };
  const startVoice = () => {
    type RecognitionEvent = { results: ArrayLike<ArrayLike<{ transcript: string }>> };
    type Recognition = { lang: string; start: () => void; onresult: (event: RecognitionEvent) => void; onerror: () => void };
    type RecognitionWindow = Window & { SpeechRecognition?: new () => Recognition; webkitSpeechRecognition?: new () => Recognition };
    const voiceWindow = window as RecognitionWindow;
    const SpeechRecognition = voiceWindow.SpeechRecognition ?? voiceWindow.webkitSpeechRecognition;
    if (!SpeechRecognition) { textareaRef.current?.focus(); setInput("Voice input isn't supported here. Type your question instead."); return; }
    const recognition = new SpeechRecognition(); recognition.lang = state.language === "te" ? "te-IN" : "en-IN"; recognition.onresult = (event) => setInput(event.results[0]?.[0]?.transcript ?? ""); recognition.onerror = () => textareaRef.current?.focus(); recognition.start();
  };
  return <div className="grid min-h-[calc(100svh-7.5rem)] gap-5 lg:grid-cols-[280px_minmax(0,1fr)]"><aside className="rounded-lg border border-border bg-card p-4 shadow-soft"><div className="flex items-center justify-between"><h2 className="font-semibold"><Translated>{"Conversations"}</Translated></h2><Button size="icon" onClick={onNew} aria-label={translateHealthText("New chat", languageForAttributes)}><Plus /></Button></div><div className="mt-4 space-y-2"><Translated>{state.threads.map((item) => <Link key={item.id} to="/chat/$threadId" params={{ threadId:item.id }} className={cn("block rounded-lg p-3 text-sm", item.id===thread?.id ? "bg-accent text-accent-foreground" : "hover:bg-muted")}><p className="truncate font-semibold"><Translated>{item.title}</Translated></p><p className="mt-1 text-xs text-muted-foreground"><Translated>{item.messages.length}</Translated> <Translated>{"messages"}</Translated></p></Link>)}</Translated></div></aside><section className="flex min-h-[650px] flex-col overflow-hidden rounded-lg border border-border bg-card shadow-soft"><header className="border-b border-border px-5 py-4"><div className="flex items-center gap-3"><BrandMark /><div><h1 className="font-semibold"><Translated>{"HealthPilot Copilot"}</Translated></h1><p className="text-xs text-muted-foreground"><Translated>{"Answers from your connected records only"}</Translated></p></div></div></header><Conversation className="min-h-0 flex-1"><ConversationContent className="mx-auto w-full max-w-3xl p-5"><Translated>{!uiMessages.length && <ConversationEmptyState icon={<HeartPulse className="size-10 text-primary" />} title={translateHealthText("Ask about your health journey", languageForAttributes)} description={translateHealthText("Try “What changed?”, “Show my medicines”, or “How should I prepare for my visit?”", languageForAttributes)}><div className="grid gap-2 sm:grid-cols-2"><Translated>{["What changed in my reports?","What medicines am I taking?","Prepare questions for my doctor","How should I handle my tiredness?"].map((q) => <button key={q} className="rounded-lg border border-border bg-background p-3 text-left text-sm font-medium hover:bg-accent" onClick={() => submit(q)}><Translated>{q}</Translated></button>)}</Translated></div></ConversationEmptyState>}{thread?.messages.map((message) => <Message key={message.id} from={message.role}><MessageContent><MessageResponse>{message.localizedText?.[state.language] ?? (message.role === "assistant" ? answerHealthQuestion(thread?.messages.slice(0, thread.messages.indexOf(message)).reverse().find(m => m.role === "user")?.text ?? "", state.language, state.patientName, state.doctorName).text : translateHealthText(message.text, state.language))}</MessageResponse><Translated>{message.role==="assistant" && message.sources?.length ? <div className="mt-3 flex flex-wrap gap-2"><span className="text-xs font-semibold text-muted-foreground"><Translated>{"Based on your records"}</Translated></span><Translated>{message.sources.map((source) => <Link key={source} to="/records" className="rounded-full border border-primary/20 bg-accent px-2.5 py-1 text-xs font-semibold text-primary"><Translated>{source}</Translated></Link>)}</Translated></div> : null}</Translated></MessageContent></Message>)}{status==="submitted" && <Message from="assistant"><MessageContent><p className="animate-pulse text-sm text-muted-foreground"><Translated>{"Reviewing the relevant records…"}</Translated></p></MessageContent></Message>}</Translated></ConversationContent><ConversationScrollButton /></Conversation><div className="border-t border-border p-4"><PromptInput onSubmit={(message) => submit(message.text)} className="mx-auto max-w-3xl bg-background"><PromptInputTextarea ref={textareaRef} value={input} onChange={(e) => setInput(e.target.value)} placeholder={translateHealthText("Ask about a report, medicine, symptom or visit…", languageForAttributes)} /><PromptInputFooter className="justify-between"><Button type="button" size="icon" variant="ghost" onClick={startVoice} aria-label={translateHealthText("Use microphone", languageForAttributes)}><Mic /></Button><PromptInputSubmit status={status} disabled={!input.trim()} /></PromptInputFooter></PromptInput><p className="mx-auto mt-2 max-w-3xl text-center text-[11px] text-muted-foreground"><Translated>{"HealthPilot AI does not diagnose. Seek qualified medical care for urgent concerns."}</Translated></p></div></section></div>;
}

function MedicationsPage({ state, setState, notify }: { state: HealthState; setState: (updater:(s:HealthState)=>HealthState)=>void; notify:(s:string)=>void }) { const languageForAttributes = useContext(HealthLanguageContext);  const markTaken = (id:string) => { const medication=state.medications.find((m)=>m.id===id); if (medication?.takenAt) { notify("This dose is already marked as taken"); return; } const time=new Date().toLocaleString([], { dateStyle:"medium", timeStyle:"short" }); setState((current)=>({...current,medications:current.medications.map((m)=>m.id===id?{...m,takenAt:time,remaining:Math.max(0,m.remaining-1)}:m)})); notify("Dose recorded in your Health Journey"); }; return <div><SectionHeading eyebrow="Current treatment plan" title={translateHealthText("Medications", languageForAttributes)} /><div className="grid gap-4 lg:grid-cols-2"><Translated>{state.medications.map((m)=><div key={m.id} className="rounded-lg border border-border bg-card p-6 shadow-soft"><div className="flex gap-4"><div className="grid size-11 shrink-0 place-items-center rounded-lg bg-accent text-primary"><Pill /></div><div className="min-w-0 flex-1"><h2 className="text-lg font-bold"><Translated>{m.name}</Translated></h2><p className="text-sm text-muted-foreground"><Translated>{m.dose}</Translated> <Translated>{"· "}</Translated><Translated>{m.schedule}</Translated></p><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><div><p className="text-2xl font-bold"><Translated>{m.remaining}</Translated></p><p className="text-xs text-muted-foreground"><Translated>{"doses remaining"}</Translated></p></div><Button onClick={()=>markTaken(m.id)} disabled={Boolean(m.takenAt)}><Translated>{m.takenAt ? <><Check /><Translated>{"Taken "}</Translated><Translated>{m.takenAt}</Translated></> : "Mark as taken"}</Translated></Button></div></div></div></div>)}</Translated></div></div>; }
function AppointmentsPage({ doctorName, onAsk }: { doctorName:string; onAsk:(q:string)=>void }) { return <div><SectionHeading eyebrow="Next visit" title={`Appointment with ${doctorName}`} /><div className="grid gap-5 lg:grid-cols-[1fr_1fr]"><div className="rounded-lg border border-border bg-card p-6 shadow-soft"><CalendarDays className="size-7 text-primary"/><h2 className="mt-5 text-xl font-bold"><Translated>{"Wednesday, 14 October"}</Translated></h2><p className="mt-1 text-muted-foreground"><Translated>{"10:30 AM · General Medicine · Hyderabad"}</Translated></p><Button className="mt-6" onClick={()=>onAsk("Prepare me for my upcoming doctor visit")}><Translated>{"Prepare for my visit"}</Translated></Button></div><div className="rounded-lg border border-border bg-card p-6 shadow-soft"><p className="text-xs font-bold uppercase text-primary"><Translated>{"Doctor visit brief"}</Translated></p><h3 className="mt-3 text-xl font-semibold"><Translated>{"What to cover"}</Translated></h3><ul className="mt-4 space-y-3 text-sm text-muted-foreground"><li><Translated>{"• Review haemoglobin and vitamin D changes"}</Translated></li><li><Translated>{"• Confirm duration of both supplements"}</Translated></li><li><Translated>{"• Discuss ongoing tiredness and progress"}</Translated></li><li><Translated>{"• Agree timing for the next blood test"}</Translated></li></ul><Button variant="outline" className="mt-6" onClick={()=>onAsk("Create my 1-minute health summary for my doctor")}><Translated>{"Create my 1-minute summary"}</Translated></Button></div></div></div>; }
function InsightsPage({ onAsk }: { onAsk:(q:string)=>void }) { const languageForAttributes = useContext(HealthLanguageContext);  return <div><SectionHeading eyebrow="Transparent trends" title={translateHealthText("Insights with a reason", languageForAttributes)} /><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><InsightCard title={translateHealthText("Two values moved upward", languageForAttributes)} body="Haemoglobin and vitamin D are higher in the latest report." source="Compared Aug 12 and Sep 15 reports"/><InsightCard title={translateHealthText("Glucose stayed similar", languageForAttributes)} body="There was a 2 mg/dL difference between the two reports." source="Compared Aug 12 and Sep 15 reports"/><InsightCard title={translateHealthText("Medicine review is due", languageForAttributes)} body="Your next visit is scheduled to review progress and supplements." source="Appointment and prescription"/></div><Button className="mt-6" onClick={()=>onAsk("Explain all my latest insights and their sources")}><Translated>{"Ask why I am seeing these insights"}</Translated></Button></div>; }
const relaxingExercises = [
  { icon: Wind, title: "Slow breathing", time: "3–5 minutes", steps: "Sit comfortably. Breathe in gently for four counts, then breathe out for six counts. Repeat without forcing the breath." },
  { icon: PersonStanding, title: "Seated stretch", time: "5 minutes", steps: "Relax your shoulders, slowly turn your head from side to side, then gently stretch your arms and upper back." },
  { icon: Activity, title: "Comfortable walk", time: "5–10 minutes", steps: "Walk at an easy pace where you can speak comfortably. Stop if you feel dizzy, faint, unusually breathless, or have chest pain." },
];
function ExercisePreview() { const languageForAttributes = useContext(HealthLanguageContext);  return <section><SectionHeading eyebrow="Calm body, calmer mind" title={translateHealthText("Simple relaxation exercises", languageForAttributes)} action={<Link to="/exercises" className="text-sm font-semibold text-primary"><Translated>{"See all three "}</Translated><ArrowRight className="inline size-4"/></Link>}/><div className="grid gap-4 md:grid-cols-3"><Translated>{relaxingExercises.map(({icon:Icon,title,time})=><div key={title} className="rounded-lg border border-border bg-card p-5 shadow-soft"><Icon className="size-5 text-primary"/><h3 className="mt-4 font-semibold"><Translated>{title}</Translated></h3><p className="mt-1 text-sm text-muted-foreground"><Translated>{time}</Translated></p></div>)}</Translated></div></section>; }
function ExercisesPage() { const languageForAttributes = useContext(HealthLanguageContext);  return <div><SectionHeading eyebrow="Gentle wellbeing" title={translateHealthText("Three mind-relaxing exercises", languageForAttributes)}/><p className="mb-7 max-w-2xl text-muted-foreground"><Translated>{"Choose a comfortable exercise. These activities may support relaxation but do not treat a medical condition."}</Translated></p><div className="grid gap-5 lg:grid-cols-3"><Translated>{relaxingExercises.map(({icon:Icon,title,time,steps},index)=><div key={title} className="rounded-lg border border-border bg-card p-6 shadow-soft"><div className="flex items-center justify-between"><div className="grid size-11 place-items-center rounded-lg bg-accent text-primary"><Icon/></div><span className="text-xs font-bold text-muted-foreground"><Translated>{time}</Translated></span></div><p className="mt-5 text-xs font-bold uppercase text-primary"><Translated>{"Exercise "}</Translated><Translated>{index+1}</Translated></p><h2 className="mt-1 text-xl font-semibold"><Translated>{title}</Translated></h2><p className="mt-3 text-sm leading-6 text-muted-foreground"><Translated>{steps}</Translated></p></div>)}</Translated></div><div className="mt-6 rounded-lg border border-warning/30 bg-muted p-4 text-sm"><strong><Translated>{"Safety:"}</Translated></strong> <Translated>{"Stop immediately if you develop chest pain, fainting, severe breathlessness, or rapidly worsening symptoms. Seek urgent medical help when needed."}</Translated></div></div>; }
function EmergencyPage() { const languageForAttributes = useContext(HealthLanguageContext);  return <div><SectionHeading eyebrow="Urgent help" title={translateHealthText("Emergency services", languageForAttributes)}/><div className="grid gap-5 lg:grid-cols-[1fr_.8fr]"><div className="rounded-lg border border-destructive/25 bg-card p-6 shadow-soft"><div className="grid size-12 place-items-center rounded-full bg-destructive/10 text-destructive"><Ambulance/></div><h2 className="mt-5 text-2xl font-semibold"><Translated>{"Should you call 108 for an ambulance?"}</Translated></h2><p className="mt-3 leading-7 text-muted-foreground"><Translated>{"Call 108 now for chest pain, severe difficulty breathing, fainting, unresponsiveness, heavy bleeding, a suspected stroke, or any rapidly worsening emergency."}</Translated></p><Button asChild className="mt-6"><a href="tel:108"><Ambulance/><Translated>{"Call 108"}</Translated></a></Button></div><div className="rounded-lg border border-border bg-card p-6 shadow-soft"><h3 className="font-semibold"><Translated>{"While help is on the way"}</Translated></h3><ul className="mt-4 space-y-3 text-sm leading-6 text-muted-foreground"><li><Translated>{"• Move to a safe place and keep the phone nearby."}</Translated></li><li><Translated>{"• Follow the emergency operator’s instructions."}</Translated></li><li><Translated>{"• Do not drive yourself if you may lose consciousness."}</Translated></li><li><Translated>{"• Keep your medicines and allergy information ready."}</Translated></li></ul><p className="mt-5 text-xs text-muted-foreground"><Translated>{"HealthPilot cannot assess an emergency. When in doubt, seek urgent professional help."}</Translated></p></div></div></div>; }
function ProfilePage({ state, onEdit }: { state: HealthState; onEdit: () => void }) { const languageForAttributes = useContext(HealthLanguageContext);  return <div><SectionHeading eyebrow="Personal health profile" title={translateHealthText("Emergency information", languageForAttributes)} action={<Button variant="outline" onClick={onEdit}><Pencil/><Translated>{"Edit names"}</Translated></Button>}/><div className="grid gap-5 md:grid-cols-2"><div className="rounded-lg border border-border bg-card p-6 shadow-soft"><p className="text-xs font-bold uppercase text-primary"><Translated>{"Personal health details"}</Translated></p><h2 className="mt-3 text-2xl font-bold"><Translated>{state.patientName}</Translated></h2><p className="mt-1 text-muted-foreground"><Translated>{"Primary doctor · "}</Translated><Translated>{state.doctorName}</Translated></p><div className="mt-6 grid grid-cols-2 gap-4"><DataPoint label="Blood group" value="B+"/><DataPoint label="Date of birth" value="17 May 1998"/><DataPoint label="Allergies" value="Penicillin"/><DataPoint label="Emergency contact" value="Ravi · +91 •••• 4482"/></div></div><div className="rounded-lg border border-destructive/20 bg-destructive/5 p-6"><p className="text-xs font-bold uppercase text-destructive"><Translated>{"Emergency card"}</Translated></p><h3 className="mt-3 font-semibold"><Translated>{"Current medications"}</Translated></h3><p className="mt-2 text-sm text-muted-foreground"><Translated>{"Ferrous Ascorbate 100 mg daily"}</Translated><br/><Translated>{"Cholecalciferol 60,000 IU weekly"}</Translated></p><h3 className="mt-5 font-semibold"><Translated>{"Important allergy"}</Translated></h3><p className="mt-2 text-sm text-muted-foreground"><Translated>{"Penicillin — recorded patient allergy"}</Translated></p></div></div></div>; }
function DataPoint({label,value}:{label:string;value:string}){return <div><p className="text-xs text-muted-foreground"><Translated>{label}</Translated></p><p className="mt-1 font-semibold"><Translated>{value}</Translated></p></div>}
function SettingsPage({ state, setState }: { state:HealthState; setState:(updater:(s:HealthState)=>HealthState)=>void }) { const languageForAttributes = useContext(HealthLanguageContext);  return <div><SectionHeading eyebrow="Preferences" title={translateHealthText("Settings", languageForAttributes)}/><div className="max-w-2xl rounded-lg border border-border bg-card p-6 shadow-soft"><h2 className="font-semibold"><Translated>{"Language"}</Translated></h2><div className="mt-4 flex gap-2"><Button variant={state.language==="en"?"default":"outline"} onClick={()=>setState(s=>({...s,language:"en"}))}><Translated>{"English"}</Translated></Button><Button variant={state.language==="te"?"default":"outline"} onClick={()=>setState(s=>({...s,language:"te"}))}><Translated>{"తెలుగు"}</Translated></Button></div><div className="mt-8 border-t border-border pt-6"><h2 className="font-semibold"><Translated>{"Connected device"}</Translated></h2><p className="mt-2 text-sm text-muted-foreground"><Translated>{state.deviceConnected?"Your selected health source is connected.":"No health device is connected."}</Translated></p></div></div></div>; }

function ProfileDialog({ open, onOpenChange, state, setState }: { open:boolean; onOpenChange:(open:boolean)=>void; state:HealthState; setState:(updater:(state:HealthState)=>HealthState)=>void }) { const [patientName,setPatientName]=useState(state.patientName); const [doctorName,setDoctorName]=useState(state.doctorName); useEffect(()=>{if(open){setPatientName(state.patientName);setDoctorName(state.doctorName);}},[open,state.patientName,state.doctorName]); const save=()=>{const patient=patientName.trim();const doctor=doctorName.trim();if(!patient||!doctor)return;setState(current=>({...current,patientName:patient,doctorName:doctor}));onOpenChange(false);}; return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle><Translated>{"Personalize HealthPilot"}</Translated></DialogTitle><DialogDescription><Translated>{"These names will appear across your dashboard, appointments, and Copilot conversations."}</Translated></DialogDescription></DialogHeader><div className="space-y-4"><label className="block text-sm font-semibold"><Translated>{"Your name"}</Translated><Input className="mt-1" value={patientName} onChange={event=>setPatientName(event.target.value)} /></label><label className="block text-sm font-semibold"><Translated>{"Doctor’s name"}</Translated><Input className="mt-1" value={doctorName} onChange={event=>setDoctorName(event.target.value)} /></label></div><DialogFooter><Button variant="outline" onClick={()=>onOpenChange(false)}><Translated>{"Cancel"}</Translated></Button><Button onClick={save} disabled={!patientName.trim()||!doctorName.trim()}><Translated>{"Save names"}</Translated></Button></DialogFooter></DialogContent></Dialog>; }

function UploadDialog({ open,onOpenChange,onSaved,onCritical }:{open:boolean;onOpenChange:(o:boolean)=>void;onSaved:()=>void;onCritical:()=>void}) { const languageForAttributes = useContext(HealthLanguageContext);  const [step,setStep]=useState(0); const [fileName,setFileName]=useState(""); const fileRef=useRef<HTMLInputElement|null>(null); const labels=["Reading document…","Finding dates and results…","Identifying medicines and measurements…","Connecting medical information…"]; useEffect(()=>{let timer: number | undefined; if(!open){setStep(0);setFileName("");} else if(step>0&&step<5){timer=window.setTimeout(()=>setStep(s=>s+1),650);} return()=>{if(timer!==undefined) window.clearTimeout(timer);};},[open,step]); return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[90svh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle><Translated>{"Upload medical record"}</Translated></DialogTitle><DialogDescription><Translated>{"Review the extracted findings carefully before saving them to your Health Journey."}</Translated></DialogDescription></DialogHeader><Translated>{step===0&&<label onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const f=e.dataTransfer.files?.[0]; if(f){setFileName(f.name);setStep(1);}}} className="grid min-h-64 cursor-pointer place-items-center rounded-lg border border-dashed border-primary/40 bg-accent p-8 text-center transition-colors hover:bg-accent/70"><input ref={fileRef} type="file" accept=".pdf,.jpg,.jpeg,.png,image/*,application/pdf" className="sr-only" aria-label={translateHealthText("Choose medical record file from your laptop", languageForAttributes)} onChange={e=>{const f=e.target.files?.[0]; if(f){setFileName(f.name);setStep(1);} e.target.value="";}}/><div><CloudUpload className="mx-auto size-10 text-primary"/><p className="mt-4 font-semibold"><Translated>{"Upload a prescription, lab report or discharge summary from your laptop"}</Translated></p><p className="mt-2 text-sm text-muted-foreground"><Translated>{"Click here to browse your files, or drag and drop. PDF, JPG or PNG"}</Translated></p><span className="mt-5 inline-flex h-10 items-center gap-2 rounded-md bg-primary px-4 text-sm font-semibold text-primary-foreground"><CloudUpload className="size-4"/><Translated>{"Browse laptop files"}</Translated></span></div></label>}{step>0&&step<5&&<div className="py-10"><div className="mx-auto size-12 animate-spin rounded-full border-4 border-accent border-t-primary"/><p className="mt-5 text-center font-semibold"><Translated>{labels[Math.min(step-1,3)]}</Translated></p><div className="mx-auto mt-5 h-2 max-w-sm overflow-hidden rounded-full bg-muted"><div className="h-full bg-primary transition-all" style={{width:`${step*22}%`}}/></div></div>}{step>=5&&<div className="space-y-4"><div className="rounded-lg bg-accent p-4 text-sm"><ShieldCheck className="mr-2 inline size-4 text-primary"/><Translated>{"Report review is ready"}</Translated><Translated>{fileName?` for “${fileName}”`:""}</Translated><Translated>{". Confirm every detail against the original document."}</Translated></div><div className="grid gap-3 sm:grid-cols-2"><Translated>{[["Record type","Lab report"],["Date","08 October 2026"],["Haemoglobin","11.6 g/dL"],["Vitamin D","24 ng/mL"]].map(([label,value])=><label key={label} className="block text-sm font-semibold"><Translated>{label}</Translated><Input defaultValue={value} className="mt-1 font-normal"/></label>)}</Translated></div><div className="rounded-lg border border-border p-4"><p className="font-semibold"><Translated>{"What the report contains"}</Translated></p><ul className="mt-3 space-y-2 text-sm text-muted-foreground"><li><Translated>{"• Haemoglobin is higher than the previous recorded result."}</Translated></li><li><Translated>{"• Vitamin D improved but remains worth reviewing with your doctor."}</Translated></li><li><Translated>{"• Glucose is similar to the previous report."}</Translated></li></ul></div><div className="rounded-lg border border-primary/20 bg-accent p-4"><p className="font-semibold text-primary"><Translated>{"Precautions and next measurements"}</Translated></p><ul className="mt-3 space-y-2 text-sm"><li><Translated>{"• Continue prescribed medicines only as directed."}</Translated></li><li><Translated>{"• Keep the planned doctor review and repeat tests."}</Translated></li><li><Translated>{"• Do not change supplement doses without clinical advice."}</Translated></li><li><Translated>{"• Seek prompt care if symptoms become severe or rapidly worsen."}</Translated></li></ul></div></div>}</Translated><DialogFooter><Translated>{step>=5&&<Button onClick={onSaved}><Translated>{"Save to Health Journey"}</Translated></Button>}</Translated></DialogFooter></DialogContent></Dialog>; }
function DeviceDialog({open,onOpenChange,onConnect}:{open:boolean;onOpenChange:(o:boolean)=>void;onConnect:()=>void}) { const options=[["Phone","Built-in phone activity sensors",Smartphone],["Apple Health","iPhone and Apple Watch",Watch],["Google Fit","Android and Wear OS",Activity],["Smartwatch","Bluetooth wearable",Watch]] as const; const nearby:Record<string,{name:string;kind:string}[]>={Phone:[{name:"My Phone",kind:"Phone"},{name:"Galaxy S24",kind:"Phone"},{name:"iPhone 15",kind:"Phone"}],"Apple Health":[{name:"Apple Watch Series 9",kind:"Watch"},{name:"iPhone 15",kind:"Phone"}],"Google Fit":[{name:"Pixel Watch 2",kind:"Watch"},{name:"Pixel 8",kind:"Phone"},{name:"Fitbit Charge 6",kind:"Band"}],Smartwatch:[{name:"Galaxy Watch 6",kind:"Watch"},{name:"Noise ColorFit Pro",kind:"Watch"},{name:"Amazfit GTR 4",kind:"Watch"},{name:"boAt Wave",kind:"Watch"}]}; const [source,setSource]=useState<string|null>(null); const [found,setFound]=useState(0); const [pairing,setPairing]=useState<string|null>(null); const [paired,setPaired]=useState<string|null>(null); const list=(source?nearby[source]:undefined)??[]; useEffect(()=>{if(!open){setSource(null);setFound(0);setPairing(null);setPaired(null);}},[open]); useEffect(()=>{if(!source||found>=list.length)return; const t=window.setTimeout(()=>setFound(f=>f+1),700); return()=>window.clearTimeout(t);},[source,found,list.length]); useEffect(()=>{if(!pairing)return; const t=window.setTimeout(()=>{setPaired(pairing);setPairing(null);},1600); return()=>window.clearTimeout(t);},[pairing]); useEffect(()=>{if(!paired)return; const t=window.setTimeout(()=>onConnect(),900); return()=>window.clearTimeout(t);},[paired,onConnect]); const scanning=Boolean(source)&&found<list.length; return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><Translated>{!source?<><DialogHeader><DialogTitle><Translated>{"Connect a health source"}</Translated></DialogTitle><DialogDescription><Translated>{"Import steps, heart rate, sleep, water and activity into your connected journey."}</Translated></DialogDescription></DialogHeader><div className="space-y-3"><Translated>{options.map(([name,desc,Icon],i)=><Button key={name} variant="outline" onClick={()=>setSource(name)} className="h-auto w-full justify-start gap-4 p-4 text-left"><div className="grid size-10 shrink-0 place-items-center rounded-lg bg-muted text-primary"><Icon/></div><div className="min-w-0 flex-1"><p className="font-semibold"><Translated>{name}</Translated></p><p className="whitespace-normal text-xs font-normal text-muted-foreground"><Translated>{desc}</Translated></p></div><Translated>{i===0&&<span className="text-xs font-semibold text-primary"><Translated>{"Recommended"}</Translated></span>}</Translated><ChevronRight className="size-4"/></Button>)}</Translated></div></>:<><DialogHeader><DialogTitle><Translated>{"Bluetooth"}</Translated></DialogTitle><DialogDescription><Translated>{"Pair a nearby device to sync with "}</Translated><Translated>{source}</Translated><Translated>{"."}</Translated></DialogDescription></DialogHeader><div className="flex items-center justify-between rounded-xl bg-muted p-4"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-full bg-primary text-primary-foreground"><Bluetooth className="size-4"/></div><p className="font-semibold"><Translated>{"Bluetooth"}</Translated></p></div><div className="flex h-6 w-11 items-center justify-end rounded-full bg-primary p-0.5"><div className="size-5 rounded-full bg-background shadow"/></div></div><div><div className="mb-2 flex items-center justify-between px-1"><p className="text-xs font-bold uppercase text-muted-foreground"><Translated>{"Available devices"}</Translated></p><Translated>{scanning&&<span className="flex items-center gap-2 text-xs text-muted-foreground"><span className="size-3 animate-spin rounded-full border-2 border-muted border-t-primary"/><Translated>{"Searching…"}</Translated></span>}</Translated></div><div className="divide-y divide-border overflow-hidden rounded-xl border border-border"><Translated>{list.slice(0,found).map(d=>{const Icon=d.kind==="Phone"?Smartphone:Watch; const busy=pairing===d.name; const done=paired===d.name; return <button key={d.name} type="button" disabled={Boolean(pairing||paired)} onClick={()=>setPairing(d.name)} className="flex w-full animate-in fade-in slide-in-from-top-1 items-center gap-3 p-4 text-left transition hover:bg-muted disabled:cursor-default"><Icon className="size-5 text-primary"/><div className="min-w-0 flex-1"><p className="font-medium"><Translated>{d.name}</Translated></p><p className="text-xs text-muted-foreground"><Translated>{done?"Connected":busy?"Pairing…":d.kind}</Translated></p></div><Translated>{busy&&<span className="size-4 animate-spin rounded-full border-2 border-muted border-t-primary"/>}{done&&<Check className="size-4 text-primary"/>}</Translated></button>;})}{found===0&&<p className="p-4 text-sm text-muted-foreground"><Translated>{"Looking for nearby devices…"}</Translated></p>}</Translated></div></div><DialogFooter><Button variant="outline" onClick={()=>{setSource(null);setFound(0);setPairing(null);setPaired(null);}}><Translated>{"Back"}</Translated></Button></DialogFooter></>}</Translated></DialogContent></Dialog>; }
function AlertDialog({open,onOpenChange}:{open:boolean;onOpenChange:(o:boolean)=>void}) { return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="border-destructive/30"><DialogHeader><div className="mb-2 grid size-12 place-items-center rounded-full bg-destructive/10 text-destructive"><AlertTriangle/></div><DialogTitle><Translated>{"Consult a doctor immediately."}</Translated></DialogTitle><DialogDescription><Translated>{"The uploaded record contains a result explicitly marked as critical. HealthPilot is not diagnosing its cause."}</Translated></DialogDescription></DialogHeader><div className="rounded-lg border border-destructive/20 bg-destructive/5 p-4"><p className="text-xs font-bold uppercase text-destructive"><Translated>{"Source record"}</Translated></p><p className="mt-2 font-semibold"><Translated>{"Urgent Lab Report · 08 Oct 2026"}</Translated></p><p className="mt-1 text-sm text-muted-foreground"><Translated>{"Glucose: 420 mg/dL · marked “CRITICAL HIGH” in the report"}</Translated></p></div><div className="rounded-lg border border-destructive/20 p-4"><p className="font-semibold"><Translated>{"Are there severe symptoms or immediate danger?"}</Translated></p><p className="mt-2 text-sm text-muted-foreground"><Translated>{"If yes, call 108 for an ambulance now. Do not wait for an online response."}</Translated></p></div><DialogFooter><Button variant="outline" onClick={()=>onOpenChange(false)}><Translated>{"Close"}</Translated></Button><Button asChild><a href="tel:108"><Ambulance/><Translated>{"Call 108"}</Translated></a></Button></DialogFooter></DialogContent></Dialog>; }
function EventDialog({event,onOpenChange,onAsk}:{event:JourneyEvent|null;onOpenChange:(o:boolean)=>void;onAsk:(q:string)=>void}) { if(!event)return null; const Icon=eventIcon[event.type]; return <Dialog open={Boolean(event)} onOpenChange={onOpenChange}><DialogContent className="sm:max-w-2xl"><DialogHeader><div className="mb-2 grid size-12 place-items-center rounded-lg bg-accent text-primary"><Icon/></div><DialogTitle><Translated>{event.title}</Translated></DialogTitle><DialogDescription><Translated>{event.date}{event.doctor?` · ${event.doctor}`:""}</Translated></DialogDescription></DialogHeader><div className="space-y-5"><div><p className="text-xs font-bold uppercase text-primary"><Translated>{"What happened"}</Translated></p><p className="mt-2 text-sm leading-6"><Translated>{event.detail}</Translated></p></div><Translated>{event.record&&<div><p className="text-xs font-bold uppercase text-primary"><Translated>{"Related record"}</Translated></p><p className="mt-2 rounded-lg bg-muted p-3 text-sm font-semibold"><Translated>{event.record}</Translated></p></div>}</Translated><div><p className="text-xs font-bold uppercase text-primary"><Translated>{"Important extracted information"}</Translated></p><ul className="mt-2 space-y-2 text-sm"><Translated>{event.extracted.map(item=><li key={item}><Translated>{"• "}</Translated><Translated>{item}</Translated></li>)}</Translated></ul></div><div className="rounded-lg border border-primary/20 bg-accent p-4"><p className="text-xs font-bold uppercase text-primary"><Translated>{"AI Connection"}</Translated></p><p className="mt-2 text-sm"><Translated>{event.connection}</Translated></p></div></div><DialogFooter><Button variant="outline" onClick={()=>onAsk(`Explain the ${event.title} from ${event.date}`)}><Bot/><Translated>{"Explain with AI"}</Translated></Button></DialogFooter></DialogContent></Dialog>; }